// AdminCompanies.jsx
// Extended: admin must validate company accounts after document verification
import { useState } from "react";
import AdminLayout from "./AdminLayout";

const SECTORS = ["All","Technology","Energy & Oil","Telecommunications","Banking & Finance","Manufacturing"];
const STATUS_FILTER = ["All","Pending","Approved","Rejected"];

const INIT_COMPANIES = [
  { id:1, name:"Sonatrach Digital",   email:"rh@sonatrach.dz",    wilaya:"Alger",  sector:"Energy & Oil",       offers:3, accepted:3, logo:"🛢️", status:"approved",  doc:"RC_sonatrach.pdf",    registeredDate:"Mar 10" },
  { id:2, name:"Djezzy Tech",          email:"rh@djezzy.dz",        wilaya:"Alger",  sector:"Telecommunications", offers:2, accepted:1, logo:"📡", status:"approved",  doc:"NIF_djezzy.pdf",      registeredDate:"Mar 15" },
  { id:3, name:"Ooredoo Labs",         email:"rh@ooredoo.dz",       wilaya:"Alger",  sector:"Telecommunications", offers:2, accepted:2, logo:"🌐", status:"approved",  doc:"CNRC_ooredoo.pdf",    registeredDate:"Mar 18" },
  { id:4, name:"BNA Digital",          email:"rh@bna.dz",           wilaya:"Alger",  sector:"Banking & Finance",  offers:1, accepted:1, logo:"🏦", status:"approved",  doc:"RC_bna.pdf",          registeredDate:"Mar 20" },
  { id:5, name:"Cevital Digital",      email:"rh@cevital.dz",       wilaya:"Béjaïa", sector:"Manufacturing",      offers:2, accepted:1, logo:"🏭", status:"approved",  doc:"NIF_cevital.pdf",     registeredDate:"Mar 22" },
  { id:6, name:"Mobilis IT",           email:"rh@mobilis.dz",       wilaya:"Oran",   sector:"Telecommunications", offers:1, accepted:1, logo:"📱", status:"approved",  doc:"CNRC_mobilis.pdf",    registeredDate:"Apr 01" },
  { id:7, name:"CERIST",               email:"rh@cerist.dz",        wilaya:"Alger",  sector:"Technology",         offers:2, accepted:1, logo:"🔬", status:"approved",  doc:"lettre_cerist.pdf",   registeredDate:"Apr 05" },
  { id:8, name:"Algérie Télécom Labs", email:"rh@algerietelecom.dz",wilaya:"Alger",  sector:"Telecommunications", offers:1, accepted:0, logo:"📞", status:"pending",   doc:"RC_at_labs.pdf",      registeredDate:"Apr 22" },
  { id:9, name:"Condor Electronics",   email:"rh@condor.dz",        wilaya:"Blida",  sector:"Manufacturing",      offers:0, accepted:0, logo:"💻", status:"pending",   doc:"CNRC_condor.pdf",     registeredDate:"Apr 24" },
  { id:10,name:"Naftal Digital",       email:"rh@naftal.dz",        wilaya:"Alger",  sector:"Energy & Oil",       offers:0, accepted:0, logo:"⛽", status:"pending",   doc:"NIF_naftal.pdf",      registeredDate:"Apr 25" },
  { id:11,name:"Fake Corp Ltd",        email:"fake@notreal.com",    wilaya:"Oran",   sector:"Technology",         offers:0, accepted:0, logo:"❓", status:"rejected",  doc:"invalid_doc.jpg",     registeredDate:"Apr 20" },
];

const STATUS_CFG = {
  pending:  { badge:"badge-orange", label:"Pending",  icon:"⏳", dot:"bg-[#d4a84b]" },
  approved: { badge:"badge-green",  label:"Approved", icon:"✅", dot:"bg-[#c97168]" },
  rejected: { badge:"badge-red",    label:"Rejected", icon:"❌", dot:"bg-[#d4849a]" },
};

export default function AdminCompanies() {
  const [companies, setCompanies] = useState(INIT_COMPANIES);
  const [search, setSearch]       = useState("");
  const [sector, setSector]       = useState("All");
  const [statusFilter, setStatusFilter] = useState("All");
  const [selected, setSelected]   = useState(null);
  const [rejectNote, setRejectNote] = useState("");
  const [showRejectInput, setShowRejectInput] = useState(false);

  const pendingCount = companies.filter(c => c.status === "pending").length;

  const handleApprove = (id) => {
    setCompanies(prev => prev.map(c => c.id===id ? {...c, status:"approved"} : c));
    setSelected(prev => prev?.id===id ? {...prev, status:"approved"} : prev);
    setShowRejectInput(false);
  };

  const handleReject = (id) => {
    setCompanies(prev => prev.map(c => c.id===id ? {...c, status:"rejected"} : c));
    setSelected(prev => prev?.id===id ? {...prev, status:"rejected"} : prev);
    setShowRejectInput(false);
    setRejectNote("");
  };
  const filtered = companies.filter(c => {
    const q = search.toLowerCase();
    const matchQ = !q || c.email.toLowerCase().includes(q) || c.wilaya.toLowerCase().includes(q);
    const matchS = sector === "All" || c.sector === sector;
    const matchSt = statusFilter === "All" || STATUS_CFG[c.status].label === statusFilter;
    return matchQ && matchS && matchSt;
  });

  return (
    <AdminLayout active="companies" pendingCount={pendingCount}>
      <div className="p-5 md:p-8">

        {/* Header */}
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-[#2E7DF7] uppercase tracking-widest mb-1">Companies</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">Company verification</h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">
            {companies.length} registered ·{" "}
            <span className="text-[#a0622a] font-medium">{pendingCount} pending review</span> ·{" "}
            {companies.filter(c=>c.status==="approved").length} approved
          </p>
        </div>

        {/* Info banner */}
        <div className="anim-fade-up anim-d1 bg-soft/40 border border-soft rounded-xl p-3 mb-5 flex gap-2 items-start">
          <span>📌</span>
          <p className="text-xs text-slate-600 leading-relaxed">
            Each company must be verified before accessing the platform. Review their registration document (RC, NIF, CNRC) then <strong>approve</strong> or <strong>reject</strong> their account.
          </p>
        </div>

        {/* Filters */}
        <div className="anim-fade-up anim-d2 card border border-slate-200 p-4 mb-5">
          <div className="flex flex-col md:flex-row gap-3">
            <div className="relative flex-1">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">🔍</span>
              <input type="text" placeholder="Search by name, email or wilaya…" value={search}
                onChange={e => setSearch(e.target.value)} className="input-field pl-9"/>
            </div>
            <select value={sector} onChange={e => setSector(e.target.value)} className="input-field md:w-48">
              {SECTORS.map(s => <option key={s}>{s}</option>)}
            </select>
            <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="input-field md:w-36">
              {STATUS_FILTER.map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
        </div>

        <div className="grid md:grid-cols-5 gap-5">

          {/* List */}
          <div className="md:col-span-2 anim-fade-up anim-d3 space-y-2">
            {filtered.map(c => {
              const sc = STATUS_CFG[c.status];
              return (
                <div key={c.id} onClick={() => { setSelected(c); setShowRejectInput(false); }}
                  className={`card border cursor-pointer transition-all p-4 ${selected?.id===c.id?"border-[#2E7DF7] bg-soft/30":"border-slate-200 hover:border-soft"}`}>
                  <div className="flex items-center gap-3">
                    <div className="w-11 h-11 rounded-xl bg-soft flex items-center justify-center text-xl shrink-0">{c.logo}</div>
                    <div className="flex-1 min-w-0">
                      <div className="font-syne font-bold text-slate-800 text-sm truncate">{c.name}</div>
                      <div className="text-xs text-slate-400">{c.sector} · {c.wilaya}</div>
                    </div>
                    <span className={`badge ${sc.badge} shrink-0`}>{sc.icon} {sc.label}</span>
                  </div>
                  <div className="flex justify-between mt-2 text-xs text-slate-400">
                    <span>📅 {c.registeredDate}</span>
                    <span>📎 {c.doc}</span>
                  </div>
                </div>
              );
            })}
            {filtered.length === 0 && (
              <div className="text-center py-14">
                <div className="text-4xl mb-2">🔍</div>
                <p className="text-sm text-slate-400">No companies match your search.</p>
              </div>
            )}
          </div>

          {/* Detail + validation */}
          <div className="md:col-span-3 anim-fade-up anim-d3">
            {selected ? (() => {
              const sc = STATUS_CFG[selected.status];
              return (
                <div className="card border border-slate-200 p-5 sticky top-4">

                  {/* Header */}
                  <div className="flex items-start gap-4 mb-5 pb-5 border-b border-slate-100">
                    <div className="w-14 h-14 rounded-2xl bg-soft flex items-center justify-center text-3xl shrink-0">{selected.logo}</div>
                    <div className="flex-1">
                      <h2 className="font-syne font-extrabold text-slate-900 text-xl">{selected.name}</h2>
                      <p className="text-slate-500 text-sm">{selected.sector}</p>
                      <div className="flex flex-wrap gap-2 mt-1.5">
                        <span className={`badge ${sc.badge}`}>{sc.icon} {sc.label}</span>
                        <span className="badge badge-slate">📍 {selected.wilaya}</span>
                      </div>
                    </div>
                  </div>

                  {/* Info */}
                  <div className="space-y-3 mb-5">
                    {[
                      {k:"Email",       v:selected.email},
                      {k:"Wilaya",      v:selected.wilaya},
                      {k:"Sector",      v:selected.sector},
                      {k:"Registered",  v:selected.registeredDate},
                      {k:"Offers posted", v:`${selected.offers}`},
                      {k:"Interns accepted", v:`${selected.accepted}`},
                    ].map(({k,v}) => (
                      <div key={k} className="flex justify-between text-sm">
                        <span className="text-slate-400">{k}</span>
                        <span className="font-medium text-slate-700">{v}</span>
                      </div>
                    ))}
                  </div>

                  {/* Verification document */}
                  <div className="mb-5">
                    <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-widest mb-2">Verification document</h4>
                    <div className="flex items-center gap-3 p-3 bg-[#fdf9f5] border border-slate-200 rounded-xl">
                      <div className="w-10 h-10 bg-cream border border-cream rounded-lg flex items-center justify-center text-lg shrink-0">📎</div>
                      <div className="flex-1 min-w-0">
                        <div className="text-sm font-semibold text-slate-700 truncate">{selected.doc}</div>
                        <div className="text-xs text-slate-400">Uploaded at registration</div>
                      </div>
                      <button className="text-xs font-semibold text-[#2E7DF7] bg-soft px-3 py-1.5 rounded-lg hover:bg-soft/70 transition-colors shrink-0">
                        View →
                      </button>
                    </div>
                  </div>

                  {/* Acceptance rate if approved */}
                  {selected.status === "approved" && selected.offers > 0 && (
                    <div className="mb-5">
                      <div className="flex justify-between items-center mb-1.5">
                        <span className="text-xs font-semibold text-slate-500">Acceptance rate</span>
                        <span className="text-xs font-bold text-[#2E7DF7]">{Math.round((selected.accepted/selected.offers)*100)}%</span>
                        </div>
                      <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                        <div className="progress-bar-inner" style={{width:`${Math.round((selected.accepted/selected.offers)*100)}%`}}/>
                      </div>
                    </div>
                  )}

                  {/* ── VALIDATION ACTIONS ── */}
                  <div className="pt-4 border-t border-slate-100">
                    <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-widest mb-3">Admin decision</h4>

                    {selected.status === "pending" && !showRejectInput && (
                      <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => setShowRejectInput(true)}
                          className="danger-btn text-white font-semibold py-3 rounded-xl text-sm">
                          ✕ Reject account
                        </button>
                        <button onClick={() => handleApprove(selected.id)}
                          className="accept-btn text-white font-semibold py-3 rounded-xl text-sm">
                          ✓ Approve account
                        </button>
                      </div>
                    )}

                    {selected.status === "pending" && showRejectInput && (
                      <div className="space-y-3">
                        <div>
                          <label className="block text-xs font-semibold text-slate-500 mb-1.5">Rejection reason (sent to company)</label>
                          <textarea rows={3} value={rejectNote} onChange={e => setRejectNote(e.target.value)}
                            placeholder="e.g. Document provided is not valid. Please resubmit with an official CNRC or NIF document."
                            className="input-field resize-none text-xs"/>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                          <button onClick={() => setShowRejectInput(false)}
                            className="py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-600 hover:bg-slate-50 transition-colors">
                            ← Back
                          </button>
                          <button onClick={() => handleReject(selected.id)}
                            className="danger-btn text-white font-semibold py-2.5 rounded-xl text-sm">
                            Confirm rejection
                          </button>
                        </div>
                      </div>
                    )}

                    {selected.status === "approved" && (
                      <div className="bg-blush/40 border border-blush rounded-xl p-3 flex items-center gap-2 text-sm text-slate-700">
                        <span>✅</span>
                        <div>
                          <div className="font-semibold">Account approved</div>
                          <div className="text-xs text-slate-500">Company can post offers and review candidates.</div>
                        </div>
                        <button onClick={() => { setCompanies(prev=>prev.map(c=>c.id===selected.id?{...c,status:"pending"}:c)); setSelected(prev=>({...prev,status:"pending"})); }}
                          className="ml-auto text-xs text-slate-400 hover:text-[#b5394e] font-medium transition-colors">
                          Revoke
                        </button>
                      </div>
                    )}

                    {selected.status === "rejected" && (
                      <div className="space-y-3">
                        <div className="bg-rose/40 border border-rose rounded-xl p-3 flex items-center gap-2 text-sm text-slate-700">
                          <span>❌</span>
                          <div>
                            <div className="font-semibold">Account rejected</div>
                            <div className="text-xs text-slate-500">Company was notified and cannot access the platform.</div>
                          </div>
                        </div>
                        <button onClick={() => handleApprove(selected.id)}
                          className="w-full accept-btn text-white font-semibold py-2.5 rounded-xl text-sm">
                          ✓ Approve anyway
                        </button>
                      </div>
                    )}
                  </div>

                </div>
              );
            })() : (
              <div className="card border border-slate-200 p-10 text-center">
                <div className="text-4xl mb-3">👆</div>
                <p className="text-sm text-slate-400">Select a company to review and validate.</p>
              </div>
            )}
          </div>

        </div>
      </div>
    </AdminLayout>
  );
}
